/* ===== مكوّنات المنصة (نفس البنية والأصناف) ===== */
const DS = {
  badge: (t, tone) => e('span', { class: 't2-pill' + (tone ? ' is-' + tone : '') }, t),
  button: function (label, o) {
    const p = o || {};
    const b = e('button', { class: 't2-btn' + (p.tone ? ' is-' + p.tone : '') + (p.size === 'sm' ? ' is-sm' : ''), type: 'button', onClick: p.onClick || null });
    if (p.disabled) b.disabled = true;
    if (p.ui) b.appendChild(frag(ui(p.ui, p.size === 'sm' ? 14 : 16)));
    b.appendChild(document.createTextNode(label));
    return b;
  },
  field: function (label, value) {
    const v = (value && value.nodeType) ? value : (value === null || value === undefined ? '' : String(value));
    const tx = String((v && v.nodeType) ? v.textContent : v).trim();
    const empty = tx === '' || tx === '—';
    return e('div', { class: 't2-field' + (empty ? ' is-empty' : '') }, [e('span', { class: 't2-field-k' }, label), e('span', { class: 't2-field-v' }, empty ? 'غيرُ مُدخَل' : v)]);
  },
  fields: (list) => e('div', { class: 't2-fields t2-desc' }, (list || []).filter(Boolean).map(function (f) { return DS.field(f[0], f[1]); })),
  editField: function (label, input) {
    if (input && input.tagName === 'INPUT' && input.type === 'checkbox') { input.classList.add('t2-switch'); return e('label', { class: 't2-field is-edit is-toggle' }, [e('span', { class: 't2-field-k' }, label), input]); }
    return e('div', { class: 't2-field is-edit' }, [e('span', { class: 't2-field-k' }, label), input]);
  },
  input: function (o) {
    const p = o || {}; const num = !!p.numeric;
    if (p.type === 'date') return datePick({ value: p.value, min: p.min, max: p.max, title: p.title, onChange: function (v) { if (p.onInput) p.onInput(v); } });
    return e('input', { class: 't2-input' + (num ? ' is-num' : ''), type: num ? 'text' : (p.type || 'text'), inputmode: num ? 'decimal' : null, dir: num ? 'ltr' : (p.dir || null),
      value: p.value === null || p.value === undefined ? '' : String(p.value), placeholder: p.placeholder || null,
      onInput: function (ev) { let v = ev.target.value; if (num) { const c = v.replace(/[٠-٩]/g, (d) => '٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[^0-9.]/g, ''); if (c !== v) ev.target.value = c; v = c; } if (p.onInput) p.onInput(v); } });
  },
  select: function (o) { return combo(o); },
  panel: function (title, note, kids, actions) {
    const acts = Array.isArray(actions) ? actions.filter(Boolean) : (actions ? [actions] : []);
    return e('section', { class: 't2-panel' }, [
      (title || note || acts.length) ? e('div', { class: 't2-panel-h' }, [e('div', { class: 't2-panel-ht' }, [title ? e('h2', { class: 't2-group-t' }, title) : null, note ? e('span', { class: 't2-group-n' }, note) : null]),
        acts.length ? e('div', { class: 't2-panel-a' }, acts) : null]) : null,
      e('div', { class: 't2-stack-tight' }, (kids || []).filter(Boolean))]);
  },
  stepper: function (steps, label, onPick) {
    return e('ol', { class: 't2-stp' + (onPick ? ' is-nav' : ''), 'aria-label': label }, steps.map(function (s, i) {
      return e('li', { class: 't2-stp-i' + (s.state ? ' is-' + s.state : ''), 'aria-current': s.state === 'now' ? 'step' : null,
        role: onPick ? 'button' : null, tabindex: onPick ? '0' : null, title: onPick ? 'انتقل إلى «' + s.label + '»' : null,
        onClick: onPick ? function () { onPick(i); } : null, onKeydown: onPick ? function (ev) { if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); onPick(i); } } : null }, [
        e('span', { class: 't2-stp-m', 'aria-hidden': 'true' }, s.state === 'done' ? '' : fmtNum(i + 1)), e('span', { class: 't2-stp-l' }, s.label),
        s.state === 'now' ? e('span', { class: 't2-stp-s' }, 'المرحلةُ الحالية') : null]);
    }));
  },
  note: function (kind, title, body, action) {
    const ic = { info: 'info', ok: 'ok', warn: 'warn' }[kind] || 'info';
    return e('div', { class: 't2-note is-' + kind, role: 'status' }, [e('span', { class: 't2-note-ico', 'aria-hidden': 'true' }, frag(tile(ic))),
      e('div', { class: 't2-note-c' }, [e('div', { class: 't2-note-t' }, title), body ? e('div', { class: 't2-note-b' }, body) : null, action ? e('div', { class: 't2-note-a' }, action) : null])]);
  },
  actionBar: function (o) {
    const btns = (o.buttons || []).filter(Boolean);
    if (!btns.length && !o.note) return null;
    return e('div', { class: 't2-abar', role: 'group', 'aria-label': 'إجراءاتُ الصفحة' }, [o.note ? e('span', { class: 't2-abar-n' }, o.note) : null, e('div', { class: 't2-abar-b' }, btns)]);
  },
  tabs: function (o) {
    return e('div', { class: 't2-tabs', role: 'tablist' }, o.items.map(function (it) {
      const on = it[0] === o.value;
      const b = e('button', { class: 't2-tab' + (on ? ' is-on' : ''), type: 'button', role: 'tab', 'aria-selected': on ? 'true' : 'false', onClick: function () { o.onChange(it[0]); } });
      if (it[2]) b.appendChild(frag(tile(it[2]))); b.appendChild(document.createTextNode(it[1])); return b;
    }));
  },
  card: function (p) {
    const b = e('button', { class: 't2-card' + (p.active ? ' is-on' : ''), type: 'button', onClick: p.onClick || null }, [
      e('span', { class: 't2-card-ico' }, frag(tile(p.icon || 'info'))),
      e('span', { class: 't2-card-b' }, [e('span', { class: 't2-card-t' }, p.title), p.note ? e('span', { class: 't2-card-d' }, p.note) : null]),
      e('span', { class: 't2-card-go', 'aria-hidden': 'true' })]);
    return b;
  },
  cardGrid: (list) => e('div', { class: 't2-grid' }, list.filter(Boolean)),
  fileCard: function (p) {
    const nm = String(p.name || 'مرفق'); const ext = (nm.split('.').pop() || '').toLowerCase();
    const kind = ext === 'pdf' ? 'PDF' : (/^(png|jpe?g|webp)$/.test(ext) ? 'IMG' : 'FILE');
    return e('div', { class: 't2-file', role: 'listitem' }, [e('span', { class: 't2-file-ic is-' + kind.toLowerCase(), 'aria-hidden': 'true' }, kind),
      e('span', { class: 't2-file-t' }, [e('b', {}, nm), p.note ? e('span', { class: 't2-file-n' }, p.note) : null]),
      e('span', { class: 't2-file-a' }, [p.status || null, p.onOpen ? DS.button('فتح', { size: 'sm', onClick: p.onOpen }) : null])]);
  },
  fileGrid: (list) => e('div', { class: 't2-files', role: 'list' }, list.filter(Boolean)),
};

