/* ===== صور البطاقة تتبدّل تلقائيًا: صورة المنتج ثم صور التصميم الأربع — للبطاقات الظاهرة فقط ===== */
let PC_T = null, PC_IO = null, PC_TICK = 0;
const PC_VIS = new Set();
function pcCycle() {
  if (!('IntersectionObserver' in window)) return;
  if (!PC_IO) PC_IO = new IntersectionObserver(function (en) { en.forEach(function (x) { if (x.isIntersecting && x.intersectionRatio > 0.5) { PC_VIS.add(x.target); const sl = x.target.querySelector('.pc-sl'); if (sl && !sl.dataset.ld) { sl.dataset.ld = '1'; sl.setAttribute('style', galBg(x.target.dataset.sku, 1)); } } else PC_VIS.delete(x.target); }); }, { root: null, threshold: [0, 0.5, 1] });
  document.querySelectorAll('#pv-host .pc:not([data-cy])').forEach(function (c) { if (!c.querySelector('.pc-sl')) return; c.dataset.cy = '1'; c.dataset.fr = '0'; PC_IO.observe(c); });
  if (PC_T) return;
  PC_T = setInterval(function () {
    PC_TICK++;
    PC_VIS.forEach(function (c) {
      if (!c.isConnected) { PC_VIS.delete(c); return; }
      if (document.hidden || c.matches(':hover') || document.querySelector('.st-modal, .pg-lb')) return;
      const all = Array.prototype.indexOf.call(c.parentNode ? c.parentNode.children : [], c);
      if ((PC_TICK + all) % 2) return; /* بطاقة وبطاقة: لا تتبدّل كلها في اللحظة نفسها */
      let fr = (Number(c.dataset.fr) + 1) % GALN; c.dataset.fr = String(fr);
      const sl = c.querySelector('.pc-sl'); if (!sl) return;
      if (fr) sl.setAttribute('style', galBg(c.dataset.sku, fr));
      c.classList.toggle('is-sl', fr > 0);
      c.querySelectorAll('.pc-pg i').forEach(function (d, k) { d.classList.toggle('is-on', k === fr); });
    });
  }, 1700);
}

/* v111 السحب فوق الشريط السفلي يمرّر المحتوى (داخل إطار الجوال حيث يكون التمرير داخليًا) */
(function () {
  const scroller = function (dock) {
    let x = dock && dock.parentElement && dock.parentElement.querySelector('.t2-main');
    while (x && x !== document.body && x !== document.documentElement) {
      const o = getComputedStyle(x).overflowY;
      if ((o === 'auto' || o === 'scroll') && x.scrollHeight > x.clientHeight + 2) return x;
      x = x.parentElement;
    }
    return null;
  };
  let st = null;
  document.addEventListener('touchstart', function (ev) {
    const d = ev.target.closest && ev.target.closest('#pv-host .t2-dock'); if (!d) { st = null; return; }
    const sc = scroller(d); st = sc ? { sc: sc, y: ev.touches[0].clientY, moved: false } : null;
  }, { passive: true });
  document.addEventListener('touchmove', function (ev) {
    if (!st) return; const y = ev.touches[0].clientY, dy = st.y - y;
    if (Math.abs(dy) > 3) { st.moved = true; st.sc.scrollTop += dy; st.y = y; if (ev.cancelable) ev.preventDefault(); }
  }, { passive: false });
  document.addEventListener('touchend', function () { st = null; }, { passive: true });
  document.addEventListener('wheel', function (ev) {
    const d = ev.target.closest && ev.target.closest('#pv-host .t2-dock'); if (!d) return;
    const sc = scroller(d); if (!sc) return; sc.scrollTop += ev.deltaY; ev.preventDefault();
  }, { passive: false });
})();

