[QT0, QT, QTS0, QTS, QTC0, QTC, QSI0, QSI, QPC0, QPC_S0].concat(QPCS).forEach(function (T) { T.hdr = Object.assign({}, TQH0, T.hdr); });
/* ترقيم الشركاء: TRA-السنة الشهر اليوم-رقم فريد، والعقد يأخذ رقم عرضه نفسه */
[QT0.num, QT.num].forEach(function (n) { n.prefix = 'TRA'; }); QCFG.prefix = 'TRA';
const qHdr = (k) => { let H = null; try { H = (QTR || QT).hdr; } catch (err) { H = null; } return !H || H[k] !== false; };
/* العرض يُرسم بقالبه مع ما اختاره المُعِدّ لهذا العرض من أقسام وترويسة */
