    root.querySelectorAll('.tp .g-fg[data-g]').forEach(function (c) { c.setAttribute('stroke-dasharray', (Number(c.getAttribute('data-g')) * 2.765).toFixed(1) + ' 276.5'); });
    root.querySelectorAll('.tp [data-gn]').forEach(function (n) { const to = Number(n.getAttribute('data-gn')), t0 = performance.now(); (function st(now) { const k = Math.min(1, (now - t0) / 1100); n.textContent = Math.round(to * (1 - Math.pow(1 - k, 3))) + '%'; if (k < 1) requestAnimationFrame(st); })(t0); });
