function alertsPage(scope, title, subtitle) {
  const P = {
    title: title, subtitle: subtitle,
    async run(host) {
      let r;
      try { r = await rpc('my_alerts', { p_scope: scope }); } catch (err) { failed(host, err, function () { P.run(host); }); return; }
      const rows = (r && r.rows) || [];
      mount(host, rows.length ? DS.timeline(rows.map(function (x) {
        return { title: x.title, meta: x.body || null, at: x.at, tone: scope === 'adm' ? 'info' : 'ok' };
      })) : DS.emptyState({ icon: 'bell', title: 'لا تنبيهاتٍ هنا', body: 'ستظهرُ هنا التنبيهاتُ الجديدةُ فورَ وصولِها.' }));
    },
  };
  return P;
}
