function memberHome(open) {
  const slot = e('div', { class: 't2-stack' });
  (async function () {
    let m;
    try { m = await loadMem(false); } catch (err) { return; }
    if (!m || !m.exists) return;
    ensureDefs();
    const t = tierOf(m.tier);
    const p = m.points || {};
    const box = frag('<section class="lux"><div class="lux-grid"><div>' + mcard(m) + '</div><div style="display:grid;gap:14px"><div><span class="eyebrow">' + t.en.toUpperCase() + ' · لوحتي</span><h2>عضويتك ' + t.en + ' — ' + t.ar + '</h2><p>نشطة حتى <bdi dir="ltr">' + day(m.expires_at) + '</bdi>.</p></div>' +
      (window.__loyHomeHTML ? window.__loyHomeHTML() : '') +
      '<div class="lux-acts"><button type="button" class="lux-btn gold" data-h="mem-level">' + tile('crown-simple', 'navy') + 'عضويتي</button><button type="button" class="lux-btn" data-h="mem-points">نقاطي</button></div></div></div></section>');
    box.addEventListener('click', function (ev) { const b = ev.target.closest('[data-h]'); if (b && open) open(b.getAttribute('data-h')); });
    slot.appendChild(box);
  })();
  return slot;
}

